package hexadecimal

// maxInt64 is the largest value representable by an int64.
const maxInt64 = int64(1<<63 - 1)

// hexError is an error returned by ParseHex. Kind is one of "syntax" or
// "range" and is used to classify the failure.
type hexError struct {
	kind   string
	detail string
}

func (e *hexError) Error() string {
	return e.kind + " error: " + e.detail
}

// hexDigit returns the value of a hexadecimal digit character, or -1 if the
// character is not a valid hexadecimal digit.
func hexDigit(c byte) int64 {
	switch {
	case '0' <= c && c <= '9':
		return int64(c - '0')
	case 'a' <= c && c <= 'f':
		return int64(c - 'a' + 10)
	case 'A' <= c && c <= 'F':
		return int64(c - 'A' + 10)
	}
	return -1
}

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent, using first principles: each character is mapped to a digit
// value and the result is accumulated from most significant to least
// significant digit as out = out*16 + digit.
//
// It returns a syntax error for strings that are empty or contain
// non-hexadecimal characters, and a range error if the value does not fit
// in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, &hexError{kind: "syntax", detail: "empty string is not a hexadecimal number"}
	}

	var out int64
	for i := 0; i < len(in); i++ {
		d := hexDigit(in[i])
		if d < 0 {
			return 0, &hexError{kind: "syntax", detail: "invalid character at position " + itoa(i)}
		}
		if out > (maxInt64-d)/16 {
			return 0, &hexError{kind: "range", detail: "value out of range for int64"}
		}
		out = out*16 + d
	}
	return out, nil
}

// itoa formats a non-negative integer as a decimal string, for error messages.
func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	var b [24]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	return string(b[i:])
}

// HandleErrors takes a list of inputs for ParseHex and returns a matching
// list of error cases: "none" for a successful parse, "syntax" for an
// invalid hexadecimal string, and "range" for a value that does not fit
// in an int64.
func HandleErrors(inputs []string) []string {
	results := make([]string, len(inputs))
	for i, in := range inputs {
		_, err := ParseHex(in)
		if err == nil {
			results[i] = "none"
			continue
		}
		if he, ok := err.(*hexError); ok {
			results[i] = he.kind
			continue
		}
		results[i] = "syntax"
	}
	return results
}
